// Кейс: .qa/tests/i18n/I18N-003.md · план: .qa/e2e-app/specs/app.md (1.26)
// RTL по координатам на подготовке к мониторингу: «בדיקת בטיחות», «מי בבריכה היום?» (заголовок, имена детей, «ילד חדש»).
// Мониторинг НЕ запускается («התחלת ניטור» на шаге 3 не нажимается), «ילד חדש» не нажимается — данных не создаёт.
// Тестовый сигнал на «בדיקת בטיחות» звучит громко.
import { by, assert, checkedFromValue } from '../../lib/appium.mjs';
import { openSafetyCheck, openCameraStep, assertRightAligned } from '../../lib/banci.mjs';

export const name = 'RTL: тексты прижаты вправо — «בדיקת בטיחות», шаг 3 «מי בבריכה היום?» (заголовок, имена детей, «ילד חדש») #50a708 @iphone @app @prod-safe';

const AVATAR = 100; // справа от имени ребёнка — аватар, от «ילד חדש» — значок «+»

export default async function (app) {
  // 1. «בדיקת בטיחות»: заголовок.
  await openSafetyCheck(app);
  await assertRightAligned(app, by.contains('בדיקת בטיחות', 'StaticText'), 'заголовок «בדיקת בטיחות»');

  // 2. Шаг 2 → галочка → «המשך» → шаг 3.
  await app.restart();
  const water = await openCameraStep(app);
  if (checkedFromValue(await water.attr('value')) !== true) await water.click();
  await app.tap(by.exact('המשך', 'Button'), { what: '«המשך» на шаге 2' });
  await app.waitFor(by.contains('מי בבריכה היום', 'StaticText'), { timeout: 15000, what: 'шаг 3 «מי בבריכה היום?» (если не открылся — «המשך» серая: подсказка камеры, см. 1.20)' });

  // 3. Заголовок шага 3.
  await assertRightAligned(app, by.contains('מי בבריכה היום', 'StaticText'), 'заголовок «מי בבריכה היום?»');

  // 4. «ילד חדש» и имена детей — строки между «בחירת כולם» и «ילד חדש», кроме «גיל N».
  const add = await app.waitFor(by.contains('ילד חדש', 'StaticText'), { what: '«ילד חדש» на шаге 3' });
  await assertRightAligned(app, null, '«ילד חדש»', { margin: AVATAR, el: add });
  const addY = (await add.rect()).y;
  const all = await app.findAll(by.contains('בחירת כולם', 'StaticText'));
  assert(all.length, '«בחירת כולם» на шаге 3');
  const topY = (await all[0].rect()).y;
  const names = [];
  for (const e of await app.findAll('type == "XCUIElementTypeStaticText"')) {
    const r = await e.rect();
    const n = String(await e.attr('name') ?? '');
    if (r.y > topY + 10 && r.y < addY - 10 && n && !/^גיל/.test(n) && !/בחירת כולם|נבחרו/.test(n)) names.push({ e, n });
  }
  assert(names.length, 'ПРЕДУСЛОВИЕ: на шаге 3 есть хотя бы один ребёнок (у аккаунта есть дети)');
  for (const { e, n } of names) await assertRightAligned(app, null, `имя ребёнка «${n}»`, { margin: AVATAR, el: e });

  // 5. Выход без запуска мониторинга.
  await app.restart();
}
